// The workflow that failed and its error, from what n8n hands an error
// workflow: execution.error for a run that failed, trigger.error for one
// that could not start at all.
const f = $input.first().json;
const error = (f.execution && f.execution.error) || (f.trigger && f.trigger.error) || {};
const where = f.execution && f.execution.lastNodeExecuted;
return [{ json: {
  id: (f.workflow && f.workflow.id) || 'unknown',
  name: (f.workflow && f.workflow.name) || 'unknown',
  error: [error.message || 'unknown error', error.description].filter(Boolean).join(': ')
    + (where ? ` (in "${where}")` : ''),
} }];

// Puts the report in plain words and sends it: to the team's group when
// /alerts set one, otherwise to each admin privately. If the group cannot be
// posted in any more, the admins get the report instead. With the reports
// off nothing is sent, and the alerts table still keeps track.
// Jira: DM42-44, DM42-39
const r = $input.first().json;

// What went wrong, as someone who does not read error messages would say
// it. The error itself stays in the alerts table for whoever fixes it.
// place: what was being reached, a source's site or a workflow's service.
function plain(error, place) {
  const e = String(error || '');
  const code = (e.match(/\b([45]\d\d)\b/) || [])[1];
  if (e === 'found nothing') return 'it found no articles at all, twice. The page or feed has probably changed.';
  if (/not active/i.test(e)) return 'a workflow it needs is switched off in n8n.';
  if (/password authentication failed|database|relation .* does not exist|:5432\b/i.test(e)) return 'the database did not answer.';
  if (/ENOTFOUND|EAI_AGAIN|getaddrinfo|incorrect host|cannot be established/i.test(e)) return `the ${place} could not be reached. It may be down, or its address may have changed.`;
  if (/ECONNREFUSED/i.test(e)) return `the ${place} refused the connection. It is probably not running.`;
  if (/ECONNRESET|socket hang up|socket disconnected|aborted/i.test(e)) return 'the connection broke off halfway.';
  if (/timeout|timed out|ETIMEDOUT/i.test(e)) return 'it took too long to answer.';
  if (code === '404' || /\bnot found\b/i.test(e)) return 'the page or feed is not there any more (404). Its address has probably changed.';
  if (code === '401' || code === '403' || /forbidden|unauthori[sz]ed|authori[sz]ation failed/i.test(e)) return `access was refused. A key or password may be wrong, or the ${place} may block automated reading.`;
  if (code && code.startsWith('5')) return `the ${place} had a fault of its own (error ${code}). That usually passes.`;
  if (/certificate|CERT_|self.signed/i.test(e)) return `the ${place}'s security certificate did not check out.`;
  if (/JSON|Unexpected token|XML|parse/i.test(e)) return 'what came back could not be read. Its format may have changed.';
  const first = e.split('\n')[0].trim();
  return first ? `something unexpected went wrong: "${first.slice(0, 140)}"` : 'something unexpected went wrong.';
}

// The workflows people would notice, in their words, and what a failure
// means for them.
const ABOUT = {
  'Collection schedule': ['Checking the sources', 'No new articles come in until it works again.'],
  'Summarisation': ['Summarising', 'New articles wait without a summary until it works again. Nothing is lost.'],
  'Tagging': ['Tagging', 'New articles wait without subject tags until it works again. Nothing is lost.'],
  'Telegram capture': ['The Telegram bot', 'I may not answer messages until it works again.'],
  'Bot commands': ["Updating the bot's command menu", 'The bot works as before. Only its list of suggested commands may be out of date.'],
  'Signal detection': ['Looking for signals', "This week's signals are missing until it works again."],
  'Alerts': ['Reporting problems', 'A problem may have gone unreported. The dashboard still shows the sources that fail.'],
  'Retention': ['Removing the text of old articles', 'Nothing is lost. It tries again the next night.'],
};

const when = (at) => DateTime.fromJSDate(new Date(at)).setZone('Europe/Helsinki').toFormat("d.L. 'at' H.mm");
const list = (names) => names.length > 1 ? `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}` : names[0];

let text = '';
if (r.workflow !== undefined) {
  if (r.tell) {
    const [what, meaning] = ABOUT[r.workflow] || [`The workflow "${r.workflow}"`, 'It tries again at its next turn.'];
    text = r.again
      ? `⚠️ ${what} still fails: ${plain(r.error, 'service')} It has failed ${r.times} times since ${when(r.since)}.\n\n${meaning}`
      : `⚠️ ${what} stopped with an error at ${$now.setZone('Europe/Helsinki').toFormat('H.mm')}: ${plain(r.error, 'service')}\n\n${meaning}`;
  }
} else {
  const broken = r.broken || [];
  const fixed = r.fixed || [];
  const parts = [];
  if (broken.length && Number(r.broken_now) === Number(r.sources) && Number(r.sources) > 1) {
    parts.push('⚠️ No source could be read in the last two checks, so the problem is probably on our side: '
      + `the server's internet connection, or n8n itself. The first error: ${plain(broken[0].error, 'site')}`);
  } else if (broken.length === 1) {
    const b = broken[0];
    parts.push(`⚠️ ${b.source} has not worked for ${b.checks} checks in a row: ${plain(b.error, 'site')}\n\n`
      + 'Its articles are missing until it works again. I will tell you when it does.');
  } else if (broken.length) {
    parts.push('⚠️ These sources have not worked for the last two checks:\n\n'
      + broken.map((b) => `• ${b.source}: ${plain(b.error, 'site')}`).join('\n')
      + '\n\nTheir articles are missing until they work again. I will tell you when they do.');
  }
  if (fixed.length) parts.push(`✅ ${list(fixed)} ${fixed.length === 1 ? 'works' : 'work'} again.`);
  const money = (n) => `€${Number(n).toFixed(2)}`;
  const b = r.budget || {};
  if (b.over) {
    parts.push(`⛔ This month's AI budget is used up: ${money(b.spent)} of ${money(b.budget)}. `
      + 'I have stopped summarising new articles from the sources. They wait, and nothing is lost. '
      + 'Links you send me, and summaries an editor asks for, are still made.\n\n'
      + `Summarising starts again on ${DateTime.fromISO(String(b.next)).toFormat('d.L.')}, `
      + "or as soon as an admin raises the budget in the dashboard's settings.");
  } else if (b.warn) {
    parts.push(`⚠️ ${Math.floor(Number(b.share) * 100)} % of this month's AI budget is used: ${money(b.spent)} of ${money(b.budget)}. `
      + 'When it is used up, I stop summarising new articles from the sources until next month. '
      + "An admin can raise the budget in the dashboard's settings.");
  }
  if (b.back) parts.push('✅ Summarising new articles from the sources is on again.');
  text = parts.join('\n\n');
}
if (!text) return [{ json: { told: 0 } }];

const chat = String(r.chat || '');
const admins = r.admins || [];
if (chat === 'off') return [{ json: { told: 0, off: true, text } }];

const send = async (chatId, message) => {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`,
    body: { chat_id: chatId, text: message, disable_web_page_preview: true },
    json: true,
  });
};
let told = 0;
let toAdmins = !chat;
if (chat) {
  try {
    await send(chat, text);
    told++;
  } catch (e) {
    // Taken out of the group, or the group is gone.
    toAdmins = true;
    text += "\n\n(I could not post this in the team's group, so it comes to you. /alerts in the group, or /alerts private, sorts that out.)";
  }
}
if (toAdmins) {
  for (const id of admins) {
    try {
      await send(id, text);
      told++;
    } catch (e) {
      // Someone who has blocked the bot. The others still hear.
    }
  }
}
if (!told && admins.length) throw new Error('Could not send the report to anyone on Telegram.');
return [{ json: { told, text } }];
